        ns = norm(sql)
        for m in re.findall(r'"([^"]{2,60})"|\'([^\']{2,60})\'', q):
            lit = m[0] or m[1]
            nl = norm(lit)
            if len(nl) < 2:
                continue
            if nl not in ns:
                return False
        return True
    except Exception:
        return True

